from django.db import migrations, models

# Insumos que pasan a depender de la linea: codigo antiguo -> nombre base.
INSUMOS_POR_LINEA = {
    "PESTILLO": "Pestillo",
    "RODAMIENTO": "Rodamiento",
}


def separar_por_linea(apps, schema_editor):
    """El insumo existente pasa a ser el de L20 y se crea el de L25 con los
    mismos valores, para que las cotizaciones no cambien hasta que el jefe
    configure el precio propio de L25."""
    Insumo = apps.get_model("core", "Insumo")
    for codigo, nombre in INSUMOS_POR_LINEA.items():
        for ins in Insumo.objects.filter(codigo=codigo):
            Insumo.objects.get_or_create(
                empresa_id=ins.empresa_id,
                codigo=f"{codigo}_L25",
                defaults={
                    "nombre": f"{nombre} Linea 25",
                    "unidad": ins.unidad,
                    "precio_paquete": ins.precio_paquete,
                    "cantidad_paquete": ins.cantidad_paquete,
                },
            )
            if Insumo.objects.filter(
                empresa_id=ins.empresa_id, codigo=f"{codigo}_L20"
            ).exists():
                continue
            ins.codigo = f"{codigo}_L20"
            ins.nombre = f"{nombre} Linea 20"
            ins.save(update_fields=["codigo", "nombre"])


def unir_por_linea(apps, schema_editor):
    """Reverso: el insumo de L20 vuelve a ser el unico; se elimina el de L25."""
    Insumo = apps.get_model("core", "Insumo")
    for codigo, nombre in INSUMOS_POR_LINEA.items():
        Insumo.objects.filter(codigo=f"{codigo}_L25").delete()
        Insumo.objects.filter(codigo=f"{codigo}_L20").update(
            codigo=codigo, nombre=nombre
        )


