    dependencies = [
        ('core', '0009_cambioregistro'),
    ]

    operations = [
        migrations.AlterField(
            model_name='insumo',
            name='codigo',
            field=models.CharField(help_text='Ej: FELPA, PESTILLO_L20, BURLETE.', max_length=30),
        ),
        migrations.RunPython(separar_por_linea, unir_por_linea),
    ]
